def is_conflicting(self) -> bool:
    """If installed version conflicts with required version."""
    # unknown installed version is also considered conflicting
    if self.installed_version == self.UNKNOWN_VERSION:
        return True

    # Use contains with prereleases=True to properly handle development versions
    from packaging.version import Version, InvalidVersion
    try:
        version = Version(self.installed_version)
        return not self._obj.specifier.contains(version, prereleases=True)
    except InvalidVersion:
        # If the installed version is not a valid version string, consider it conflicting
        return True
